// rt_trap_ecall.S
//
// Lock-step DV gate fixture (cosim_redesign F6). A self-contained,
// self-initializing testbench: it writes EVERY GPR to a known value before
// the ROI, so the QEMU-vs-RTL reset-state difference (QEMU seeds a0/a1/.. with
// boot args; the RTL resets GPRs to 0) has vanished by the arm point. Lock-step
// arms at `roi_start` (`--pc-start roi_start`), so the init prologue executes
// on both engines but is not recorded; record 0 is the ROI's first attempt
// with identical architectural state on both sides.
//
// The ROI exercises the trap path the PM decision (traps in scope) requires:
// two M-mode ecalls, each trapping to a handler that bumps mepc by 4 and
// mret's back. At each handler-entry attempt mcause==11 (ecall-from-M) and
// mepc are compared across the engines (lock-step diff compares the trap
// cause), so a mishandled trap on the DUT would diverge loudly. Exit is via
// the SimControl device (0xe0080000), which both QEMU's andes_ae350 and vsim
// model -- no semihosting, so the same ELF lock-steps on both legs.

.section .text
.globl _start
_start:
    // Trap vector -> trap_handler (Direct mode: low 2 bits 0).
    la      t0, trap_handler
    csrw    mtvec, t0

    // Initialize every GPR x1..x31 to a known value. After this, the two
    // engines agree on all architectural registers regardless of reset
    // conventions, so the ROI comparison starts from a common state.
    li      x1,  0x101
    li      x2,  0x202
    li      x3,  0x303
    li      x4,  0x404
    li      x5,  0x505
    li      x6,  0x606
    li      x7,  0x707
    li      x8,  0x808
    li      x9,  0x909
    li      x10, 0x0a0a
    li      x11, 0x0b0b
    li      x12, 0x0c0c
    li      x13, 0x0d0d
    li      x14, 0x0e0e
    li      x15, 0x0f0f
    li      x16, 0x1010
    li      x17, 0x1111
    li      x18, 0x1212
    li      x19, 0x1313
    li      x20, 0x1414
    li      x21, 0x1515
    li      x22, 0x1616
    li      x23, 0x1717
    li      x24, 0x1818
    li      x25, 0x1919
    li      x26, 0x1a1a
    li      x27, 0x1b1b
    li      x28, 0x1c1c
    li      x29, 0x1d1d
    li      x30, 0x1e1e
    li      x31, 0x1f1f

.globl roi_start
roi_start:
    // Straight-line work + two trapping ecalls. Each ecall: mcause=11,
    // mepc=<ecall pc>; the handler advances mepc by 4 and returns.
    addi    a0, a0, 1
    ecall
    addi    a1, a1, 2
    ecall
    add     a2, a0, a1

    // Exit 0 via SimControl (works on both engines).
    li      t3, 0xe0080000
    sw      x0, 0(t3)
hang:
    j       hang

// Synchronous trap handler: skip the trapping instruction (all traps here are
// 4-byte ecalls) and return. Reads mcause/mepc into GPRs so the values also
// surface in the compared register file.
.align 2
trap_handler:
    csrr    t1, mcause
    csrr    t2, mepc
    addi    t2, t2, 4
    csrw    mepc, t2
    mret

// Wire contract between the QEMU TCG plugin and vsim. Both sides write/read
// `struct hybrid_state_v1` byte-for-byte through a shared file.
//
// Stability: never repurpose offsets within a published version. Add new
// fields by consuming bytes from `reserved`, or by introducing v2 alongside.
//
// Endianness: multi-byte fields are little-endian (native on RV64 + x86-64
// host). The format is not endian-portable; cross-endian use would need an
// explicit byte-swap path.
//
// C and C++ both compile this header.

#ifndef HYBRID_STATE_ABI_H
#define HYBRID_STATE_ABI_H

#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

#define HYBRID_STATE_MAGIC   0x42594841u  // 'AHYB' little-endian
// Version 2 (L11): vreg[] widened from 64 to 128 bytes per register, which
// shifts every field after it. Readers reject version-1 files loudly (all
// three consumers check magic + version + size) instead of mis-parsing them.
#define HYBRID_STATE_VERSION 2u

#define HYBRID_FLAG_RV64 (1u << 0)
#define HYBRID_FLAG_FP   (1u << 1)
#define HYBRID_FLAG_V    (1u << 2)

// VLEN upper bound, in bytes: 128 covers the supported engine range
// VLEN 128..1024 (L11; also QEMU's RV_VLEN_MAX). This is the wire-format
// span per vector register; the LIVE width is the runtime `vlenb` field
// below, so one struct layout serves every engine config and the legs
// never disagree on offsets. A producer whose vlenb exceeds this ceiling
// must refuse to drain (see hybrid_v_drain_policy) rather than truncate.
#define HYBRID_VLEN_BYTES_MAX 128

// L26: bytes reserved for the V-register transport scratch page -- 32 vector
// registers at the wire-format span. The driver maps this many bytes ABOVE
// the program's --mem-size (so the scratch sits past the program's RAM), and
// vsim's v_scratch_gpa() / kVScratchBytes use the same count. Shared here so
// the producer (driver mmap sizing) and consumer (vsim sweep) never disagree.
#define HYBRID_V_SCRATCH_BYTES (32 * HYBRID_VLEN_BYTES_MAX)

// 64 PMP entries; pmpcfg slots reserved at 16 so the layout works for both
// RV64 (8 entries/CSR) and a future RV32 (4 entries/CSR) packing.
#define HYBRID_PMP_CFG_NUM  16
#define HYBRID_PMP_ADDR_NUM 64

// All fields are naturally 8-byte aligned, so __attribute__((packed)) is
// unnecessary and would force unaligned access codegen. Layout is locked by
// the static_asserts in state_abi_check.h.
struct hybrid_state_v1 {
  uint32_t magic;
  uint32_t version;
  uint32_t flags;
  uint32_t hart_id;
  uint64_t pc;
  uint64_t priv;  // 0=U, 1=S, 3=M

  uint64_t gpr[32];
  uint64_t fpr[32];

  uint64_t mstatus;
  uint64_t mepc;
  uint64_t mtvec;
  uint64_t mcause;
  uint64_t mtval;
  uint64_t mscratch;
  uint64_t medeleg;
  uint64_t mideleg;
  uint64_t mip;
  uint64_t mie;
  uint64_t mcycle;
  uint64_t minstret;
  uint64_t satp;

  uint64_t pmpcfg[HYBRID_PMP_CFG_NUM];
  uint64_t pmpaddr[HYBRID_PMP_ADDR_NUM];

  uint64_t vstart;
  uint64_t vtype;
  uint64_t vl;
  uint64_t vlenb;
  uint8_t  vreg[32 * HYBRID_VLEN_BYTES_MAX];
  uint64_t vxsat;
  uint64_t vxrm;
  uint64_t vcsr;

  // F13: warmup-window snapshot of cycle/instret counters, captured K insns
  // after vsim entry. Drain-only metadata; ResumeDriver never restores them.
  // Both zero when --vsim-warmup-icount=0 or the workload exited inside the
  // warmup window. Consumes 16 bytes from the original 232-byte reserved tail.
  uint64_t mcycle_at_measure_start;
  uint64_t minstret_at_measure_start;

  // L20: FP control/status -- frm[7:5] | fflags[4:0], live when
  // HYBRID_FLAG_FP is set. Drained by the plugin, restored by ResumeDriver,
  // re-read by StateDrain. Pre-L20 state files carry 0 here (reserved bytes
  // are written as zero), which reads back as the reset value (RNE, no
  // flags) -- exactly the old behavior, so no version bump.
  uint64_t fcsr;

  // Andes machine-setup CSRs: mcache_ctl (0x7CA) enables the L1 I/D caches,
  // mmisc_ctl (0x7D0) holds misc machine config. crt0 writes them once at
  // boot; transporting them keeps the cycle engine from resuming caches-off
  // (ResumeDriver has the full rationale). Drained by the plugin, restored by
  // ResumeDriver, but NOT re-read by StateDrain: they are boot-static and the
  // drained value is unused (no QEMU2 leg). Old state files carry 0 here
  // (reset value), which is the pre-existing behavior, so no version bump.
  uint64_t mcache_ctl;
  uint64_t mmisc_ctl;

  uint8_t  reserved[192];  // zero-initialise on write; 256 - 3*8 (vxsat/vxrm/vcsr) - 2*8 (warmup) - 8 (fcsr) - 2*8 (mcache_ctl/mmisc_ctl)
};

#ifdef __cplusplus
}  // extern "C"
#endif

#include "hybrid/state_abi_check.h"

#endif  // HYBRID_STATE_ABI_H

