65	  static constexpr uint16_t kCsrVxrm     = 0x00A;
66	  static constexpr uint16_t kCsrVcsr     = 0x00F;
67	  static constexpr uint16_t kCsrVtype    = 0xC21;
68	  static constexpr uint16_t kCsrVl       = 0xC20;
69	
70	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
71	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
72	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
73	
74	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
75	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
76	
77	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
78	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
79	
80	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
81	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
82	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
83	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
84	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
85	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
86	
87	  static constexpr unsigned kPollIterations = kDmiPollIterations;
88	
89	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
90	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
91	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
92	  // GPA still unset throws in the sweep (no silent transport via a bogus
93	  // address). The simulator passes the real value from platform.main_memory.
94	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset)
95	      : bus_{bus}, scratch_gpa_{scratch_gpa}
96	  {}
97	
98	  void resume(const hybrid_state_v1& state)
99	  {
100	    if (state.magic != HYBRID_STATE_MAGIC)
101	      throw std::runtime_error("ResumeDriver::resume: bad magic");
102	    if (state.version != HYBRID_STATE_VERSION)
103	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
104	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
105	    if (state.priv == 2 || state.priv > 3)
106	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
107	
108	    // dmactive must transition 0->1 in its own write before any other
109	    // DMCONTROL bit is honored (RISC-V Debug Spec).
110	    bus_.write(kDmcontrol, kDmcontrolDmactive);
111	    request_halt();
112	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
113	
114	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
115	    // accepted (FS or VS == Off disables the extension and the hart NACKs
116	    // the writes). The drained state.mstatus may legitimately carry FS or
117	    // VS at Off (e.g. an OS context-switched the regs away before the
118	    // trigger fired) -- gating the write on the drained field skips the
119	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
120	    // write mstatus when either extension is in scope; force-OR Initial
121	    // when the drained field is Off. This enable is local to the vsim
122	    // phase; the state.mstatus written to the handoff file is left
123	    // unmodified.
124	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
125	      uint64_t enable_mstatus = state.mstatus;
126	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
127	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
128	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
129	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
130	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
131	    }
132	
133	    // FPR restore (requires mstatus.FS enabled above).
134	    if (state.flags & HYBRID_FLAG_FP) {
135	      for (uint16_t i = 0; i < 32; ++i)
136	        write_64bit_register(regno_fpr(i), state.fpr[i]);
137	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
138	      // fallback scratch x5 is overwritten by the GPR loop below.
139	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
140	    }
141	
142	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
143	    // the GPR loop overwrites x5 afterward so state is preserved).
144	    if (state.flags & HYBRID_FLAG_V) {
145	      // V data regfile: reload v0..v31 from the shared scratch region via the
146	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
147	      // because the sweep's own vsetvl (e8/m1) clobbers vtype/vl/vstart, which
148	      // the restore then overwrites with the architectural values. The sweep
149	      // uses x5/x6/x7 as scratch (x7 is the base pointer); the GPR loop below
150	      // restores all three. The wire format reserves HYBRID_VLEN_BYTES_MAX per
151	      // register, so that -- not the runtime vlenb -- is the scratch stride.
152	      if (scratch_gpa_ == kVScratchGpaUnset)
153	        throw std::runtime_error(
154	          "ResumeDriver::resume: V state present but scratch GPA unset");
155	      pb_v_data_sweep(bus_, scratch_gpa_, HYBRID_VLEN_BYTES_MAX, state.vlenb,
156	                      /*load=*/true);
157	
158	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
159	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
160	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
161	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
162	      write_64bit_register(regno_gpr(5), state.vl);
163	      write_64bit_register(regno_gpr(6), state.vtype);
164	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
165	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
166	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
167	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
168	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
169	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
170	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
171	    }
172	
173	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
174	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
175	    // in the drained privilege; M-mode states skip the write (prv already 3).
176	    // Before the GPR loop: a PB fallback would clobber scratch x5.
177	    if (state.priv != 3) {
178	      // L2 slice: with PMP implemented and no matching entry, every S/U
179	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
180	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
181	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
182	      // RV64. Tolerant writes: entries beyond what the hart implements
183	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
184	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
185	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
186	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
187	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
188	
189	      const uint64_t dcsr =
190	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
191	      write_csr_abstract_or_pb(kCsrDcsr,
192	                               (dcsr & ~uint64_t{0x3}) | state.priv);
193	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
194	      // silently measure the ROI in the wrong privilege. Verify and abort.
195	      const uint64_t got =
196	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
197	        & 0x3u;
198	      if (got != state.priv)
199	        throw std::runtime_error(
200	          "ResumeDriver::resume: engine does not implement privilege level "
201	          + std::to_string(state.priv)
202	          + " (dcsr.prv pinned to " + std::to_string(got)
203	          + "); pick an S/U-capable engine");
204	    }
205	
206	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
207	    for (uint16_t i = 1; i < 32; ++i)
208	      write_64bit_register(regno_gpr(i), state.gpr[i]);
209	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
210	
211	    write_csr_tolerant(kCsrMtvec, state.mtvec);
212	
213	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
214	    // register with no hardware side effects, legal to use inside a trap-free
215	    // ROI. Restore it so a value stashed before the handoff survives into the
216	    // vsim phase.
217	    write_csr_tolerant(kCsrMscratch, state.mscratch);
218	
219	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
220	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
221	    // value stashed before the handoff must survive into the vsim phase (same
222	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
223	    // hardware-driven pending bits, or mtval on a core that hardwires it)
224	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
225	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
226	    write_csr_tolerant(kCsrMepc,   state.mepc);
227	    write_csr_tolerant(kCsrMcause, state.mcause);
228	    write_csr_tolerant(kCsrMtval,  state.mtval);
229	    write_csr_tolerant(kCsrMie,    state.mie);
230	    write_csr_tolerant(kCsrMip,    state.mip);
231	
232	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
233	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
234	    // caches) but has no cache model, so without this the cycle engine resumes
235	    // at the ROI with caches at their reset default -- DISABLED -- and the
236	    // whole measured window runs uncached, inflating it severalfold. Tolerant
237	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
238	    // write as a no-op, and a drained 0 (caches were off) restores the reset
239	    // state, so this is always safe to issue.
240	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
241	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
242	
243	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
244	    // from QEMU1's drain value. Without this, vsim's local counter starts
245	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
246	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
247	    // overwrite here as the GPR loop already ran.
248	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
249	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
250	
251	    clear_cmderr_if_set();
252	    request_resume();
253	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
254	                   "ResumeDriver resume");
255	  }
256	
257	private:
258	  void request_halt()
259	  {
260	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
261	  }
262	
263	  void request_resume()
264	  {
265	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
266	  }
267	
268	  void write_64bit_register(uint16_t regno, uint64_t value)
269	  {
270	    write_register_abstract(bus_, regno, value);
271	  }
272	
273	  // Abstract-first CSR write with Program Buffer fallback.
274	  // Tries an abstract register write; if the DM signals cmderr, clears it,
275	  // stages the value in scratch_gpr via abstract GPR write, then executes a
276	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
277	  // to x5 (t0) which the GPR restore loop overwrites later.
278	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
279	                                 uint8_t scratch_gpr = 5)
280	  {
281	    write_64bit_register(regno_csr(csr), value);
282	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
283	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
284	    write_64bit_register(regno_gpr(scratch_gpr), value);
285	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
286	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
287	  }
288	
289	  // Write a CSR-addressable register and clear any cmderr the DM raised.
290	  // Used for CSRs whose abstract-access support may be implementation
291	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
292	  // remaining writes.
293	  void write_csr_tolerant(uint16_t csr, uint64_t value)
294	  {
295	    write_64bit_register(regno_csr(csr), value);
296	    clear_cmderr_if_set();
297	  }
298	
299	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
300	  // is rejected until the bits are W1C-cleared. We tolerate per-register
301	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
302	  // error before resuming so the hart isn't left in a stuck state.
303	  // B17: record the last observed non-zero cmderr and a clear count so a
304	  // partially-broken restore is observable via the public accessors
305	  // instead of silently swallowed.
306	  void clear_cmderr_if_set()
307	  {
308	    const auto status = bus_.read(kAbstractcs);
309	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
310	    if (code != 0u) {
311	      last_observed_cmderr_ = code;
312	      ++cmderr_clear_count_;
313	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
314	    }
315	  }
316	
317	  DmiBus& bus_;
318	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
319	  uint32_t last_observed_cmderr_ = 0;
320	  uint64_t cmderr_clear_count_   = 0;
321	
322	public:
323	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
324	  // at least one abstract write tripped a sticky cmderr the restore
325	  // tolerated by clearing. cmderr_clear_count() is the total number of
326	  // such clears across all calls into clear_cmderr_if_set() this run.
327	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
328	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
329	};
330	
331	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
332	// via an Abstract Command. Halts-and-reads contract: caller must have the
333	// hart in the halted state. Shared by StateDrain (drain at exit), and by
334	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
335	// goes sticky after the command, the helper clears it and reports 0
336	// rather than blocking the caller -- a missing CSR mirrors as zero
337	// instead of corrupting the adjacent field.
338	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
339	                                     const char* poll_label
340	                                       = "read_register_64")
341	  -> std::optional<uint64_t>
342	{
343	  using RD = ResumeDriver;
344	  bus.write(RD::kCommand,
345	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
346	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
347	  const auto status = bus.read(RD::kAbstractcs);
348	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
349	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
350	    return std::nullopt;
351	  }
352	  const uint64_t lo = bus.read(RD::kData0);
353	  const uint64_t hi = bus.read(RD::kData1);
354	  return lo | (hi << 32);
355	}
356	
357	inline auto read_register_64(DmiBus& bus, uint16_t regno,
358	                             const char* poll_label = "read_register_64")
359	  -> uint64_t
360	{
361	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
362	}
363	
364	}  // namespace hybrid
