1	// ResumeDriver translates a hybrid_state_v1 into a sequence of DMI register
2	// ops against the RISC-V Debug Module. The orchestration is testable in
3	// isolation by injecting a recording bus.
4	
5	#include "hybrid/abstract_command.hpp"
6	#include "hybrid/program_buffer.hpp"
7	#include "hybrid/resume_driver.hpp"
8	#include "hybrid/state_abi.h"
9	#include "hybrid/v_regfile_xfer.hpp"
10	
11	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
12	#include <doctest.h>
13	
14	#include <cstdint>
15	#include <deque>
16	#include <optional>
17	#include <set>
18	#include <unordered_map>
19	#include <vector>
20	
21	namespace {
22	
23	// DMI register addresses from RISC-V Debug Spec 1.0.
24	constexpr uint8_t kDmcontrol  = 0x10;
25	constexpr uint8_t kDmstatus   = 0x11;
26	constexpr uint8_t kAbstractcs = 0x16;
27	constexpr uint8_t kCommand    = 0x17;
28	constexpr uint8_t kData0      = 0x04;
29	constexpr uint8_t kData1      = 0x05;
30	
31	// CSR numbers from Debug Spec.
32	constexpr uint16_t kCsrDpc  = 0x7B1;
33	constexpr uint16_t kCsrDcsr = 0x7B0;
34	
35	// L26: the V scratch GPA is a runtime value (mmap top page) passed to the
36	// driver. Tests pass this distinctive stand-in and assert the sweep uses it.
37	constexpr uint64_t kScratch = 0x07FFF000ull;  // 128 MiB mmap top page
38	
39	struct DmiOp
40	{
41	  enum class Kind
42	  {
43	    Write,
44	    Read,
45	  };
46	  Kind kind;
47	  uint8_t reg;
48	  uint32_t value;  // for writes only
49	};
50	
51	struct RecordingBus final : hybrid::DmiBus
52	{
53	  std::vector<DmiOp> ops;
54	
55	  // Test-controlled response values for reads.
56	  uint32_t dmstatus_value = 0;       // bit 9: allhalted, bit 17: allresumeack
57	  uint32_t abstractcs_value = 0;     // fallback when queue is empty
58	  std::deque<uint32_t> abstractcs_queue; // queued reads drain first
59	
60	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
61	  // cmderr (cleared by the W1C abstractcs write the driver issues on its PB
62	  // fallback). Models real hardware and -- unlike positional queueing -- is
63	  // robust to however many unrelated abstract ops precede the targeted write.
64	  std::optional<uint16_t> fail_csr_write;
65	
66	  // One-shot: when true, the NEXT kExecProgbufCmd write raises sticky cmderr
67	  // (so exec_progbuf throws after its post-exec abstractcs poll). The flag
68	  // re-arms to false after firing - tests can flip it back on to fail a
69	  // later PB exec.
70	  bool fail_next_pb_exec = false;
71	
72	  // Mini register file: abstract write-COMMANDs latch the staged DATA0/DATA1
73	  // into regfile[regno]; abstract read-COMMANDs load it back so read-modify-
74	  // write-verify sequences observe their own writes. Regnos in warl_ignore
75	  // model WARL fields the hart pins (the write is recorded but discarded),
76	  // e.g. dcsr.prv on a core without S/U modes.
77	  std::unordered_map<uint16_t, uint64_t> regfile;
78	  std::set<uint16_t> warl_ignore;
79	
80	  void write(uint8_t reg, uint32_t value) override
81	  {
82	    ops.push_back({DmiOp::Kind::Write, reg, value});
83	    if (reg == kData0) staged_data0_ = value;
84	    if (reg == kData1) staged_data1_ = value;
85	    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
86	      cmderr_sticky_ = false;  // W1C clear
87	    if (reg == kCommand && fail_csr_write) {
88	      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
89	      const bool is_write = ((value >> 16) & 1u) != 0u;
90	      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
91	        cmderr_sticky_ = true;
92	    }
93	    if (reg == kCommand && value != hybrid::kExecProgbufCmd) {
94	      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
95	      const bool is_write = ((value >> 16) & 1u) != 0u;
96	      if (is_write) {
97	        if (!warl_ignore.count(regno))
98	          regfile[regno] = (uint64_t{staged_data1_} << 32) | staged_data0_;
99	      } else {
100	        const auto it = regfile.find(regno);
101	        const uint64_t v = (it == regfile.end()) ? 0u : it->second;
102	        pending_data0_ = static_cast<uint32_t>(v);
103	        pending_data1_ = static_cast<uint32_t>(v >> 32);
104	      }
105	    }
106	    if (reg == kCommand && value == hybrid::kExecProgbufCmd
107	        && fail_next_pb_exec) {
108	      cmderr_sticky_ = true;
109	      fail_next_pb_exec = false;
110	    }
111	  }
112	
113	  auto read(uint8_t reg) -> uint32_t override
114	  {
115	    ops.push_back({DmiOp::Kind::Read, reg, 0});
116	    if (reg == kDmstatus) return dmstatus_value;
117	    if (reg == kData0)   return pending_data0_;
118	    if (reg == kData1)   return pending_data1_;
119	    if (reg == kAbstractcs) {
120	      if (cmderr_sticky_) return kCmderrMask;
121	      if (!abstractcs_queue.empty()) {
122	        auto v = abstractcs_queue.front();
123	        abstractcs_queue.pop_front();
124	        return v;
125	      }
126	      return abstractcs_value;
127	    }
128	    return 0;
129	  }
130	
131	private:
132	  static constexpr uint32_t kCmderrMask = 0x7u << 8;
133	  bool cmderr_sticky_ = false;
134	  uint32_t staged_data0_  = 0;
135	  uint32_t staged_data1_  = 0;
136	  uint32_t pending_data0_ = 0;
137	  uint32_t pending_data1_ = 0;
138	};
139	
140	auto rv64_state(uint64_t pc, uint64_t x10) -> hybrid_state_v1
141	{
142	  hybrid_state_v1 s{};
143	  s.magic = HYBRID_STATE_MAGIC;
144	  s.version = HYBRID_STATE_VERSION;
145	  s.flags = HYBRID_FLAG_RV64;
146	  s.pc = pc;
147	  s.priv = 3;
148	  s.gpr[10] = x10;
149	  return s;
150	}
151	
152	auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
153	  -> std::vector<uint32_t>
154	{
155	  std::vector<uint32_t> values;
156	  for (const auto& op : ops)
157	    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
158	      values.push_back(op.value);
159	  return values;
160	}
161	
162	auto count_writes_to(const std::vector<DmiOp>& ops, uint8_t reg) -> std::size_t
163	{
164	  std::size_t n = 0;
165	  for (const auto& op : ops)
166	    if (op.kind == DmiOp::Kind::Write && op.reg == reg) ++n;
167	  return n;
168	}
