198	TEST_CASE("resume programs x1..x31 via DATA0/DATA1 + COMMAND, skipping x0")
199	{
200	  RecordingBus bus;
201	  bus.dmstatus_value = (1u << 9) | (1u << 17);
202	
203	  auto s = rv64_state(0x80001000, 0xdeadbeef);
204	  for (int i = 0; i < 32; ++i) s.gpr[i] = 0xa00000000ULL + i;
205	
206	  hybrid::ResumeDriver driver(bus, kScratch);
207	  driver.resume(s);
208	
209	  std::vector<uint32_t> cmds;
210	  for (const auto& op : bus.ops)
211	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
212	      cmds.push_back(op.value);
213	
214	  CHECK(cmds.size() >= 31);
215	
216	  for (int i = 1; i < 32; ++i) {
217	    const auto expect =
218	      hybrid::access_register_command(hybrid::regno_gpr(i),
219	                                      hybrid::AarSize::Bits64, /*write=*/true);
220	    CHECK(cmds[i - 1] == expect);
221	  }
222	
223	  for (const auto& cmd : cmds) {
224	    const uint16_t regno = cmd & 0xffffu;
225	    CHECK(regno != hybrid::regno_gpr(0));
226	  }
227	}
