229	TEST_CASE("resume writes DPC = state.pc")
230	{
231	  RecordingBus bus;
232	  bus.dmstatus_value = (1u << 9) | (1u << 17);
233	
234	  constexpr uint64_t pc = 0x12345678'9ABCDEF0ULL;
235	  hybrid::ResumeDriver driver(bus, kScratch);
236	  driver.resume(rv64_state(pc, 0));
237	
238	  // Look for the COMMAND write that targets CSR DPC (regno=0x7B1).
239	  std::vector<std::size_t> dpc_cmd_indices;
240	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
241	    const auto& op = bus.ops[i];
242	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
243	        && (op.value & 0xffffu) == kCsrDpc) {
244	      dpc_cmd_indices.push_back(i);
245	    }
246	  }
247	  REQUIRE(dpc_cmd_indices.size() == 1);
