262	TEST_CASE("resume issues resumereq after register programming")
263	{
264	  RecordingBus bus;
265	  bus.dmstatus_value = (1u << 9) | (1u << 17);
266	
267	  hybrid::ResumeDriver driver(bus, kScratch);
268	  driver.resume(rv64_state(0x80001000, 0));
269	
270	  // The last DMCONTROL write must clear haltreq and set resumereq.
271	  const auto dmctl_writes = find_write(bus.ops, kDmcontrol);
