329	auto cmd_regnos(const std::vector<DmiOp>& ops) -> std::vector<uint16_t>
330	{
331	  std::vector<uint16_t> ns;
332	  for (const auto& op : ops)
333	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
334	      ns.push_back(static_cast<uint16_t>(op.value & 0xffffu));
335	  return ns;
336	}
