755	            d1.reg == kData1 && d1.value == uint32_t(s.vl >> 32))
756	          found_x5_vl = true;
757	      }
758	      if (regno == hybrid::regno_gpr(6) && i >= 2) {
759	        const auto& d0 = bus.ops[i - 2];
760	        const auto& d1 = bus.ops[i - 1];
761	        if (d0.reg == kData0 && d0.value == uint32_t(s.vtype & 0xFFFFFFFFu) &&
762	            d1.reg == kData1 && d1.value == uint32_t(s.vtype >> 32))
763	          found_x6_vtype = true;
764	      }
765	    }
766	    if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
767	        && op.value == expected_vsetvl)
768	      found_vsetvl = true;
769	  }
770	  CHECK(found_x5_vl);
771	  CHECK(found_x6_vtype);
772	  CHECK(found_vsetvl);
773	}
