1002	TEST_CASE("B9: write_csr_abstract_or_pb busy-poll precedes cmderr inspection")
1003	{
1004	  // The B9 audit claimed write_csr_abstract_or_pb reads abstractcs without
1005	  // first polling busy. In fact write_64bit_register -> write_register_abstract
1006	  // calls poll_until_clear(busy) before returning, so by the time the cmderr
1007	  // check runs, busy is already clear. This test pins that contract: between
1008	  // every kCommand write and the next kAbstractcs read, the recorded ops
1009	  // must include at least one kAbstractcs read (the busy poll). If a future
1010	  // refactor regresses by removing the chained poll, this test fails.
1011	  RecordingBus bus;
1012	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1013	
1014	  hybrid::ResumeDriver driver(bus, kScratch);
1015	  driver.resume(rv64_state(0x80001000, 0xdeadbeef));
1016	
1017	  // Walk ops; between each kCommand write and the very next kAbstractcs
1018	  // read by an unrelated caller, there must be at least one kAbstractcs
1019	  // read (the busy poll from write_register_abstract).
1020	  bool saw_cmd = false;
1021	  std::size_t reads_since_cmd = 0;
1022	  bool all_cmds_had_abstractcs_poll = true;
1023	  for (const auto& op : bus.ops) {
1024	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
1025	      if (saw_cmd && reads_since_cmd == 0)
1026	        all_cmds_had_abstractcs_poll = false;
1027	      saw_cmd = true;
1028	      reads_since_cmd = 0;
1029	    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
1030	               && op.reg == kAbstractcs) {
1031	      ++reads_since_cmd;
1032	    }
1033	  }
1034	  CHECK(all_cmds_had_abstractcs_poll);
1035	  // The final kCommand write must also be followed by an abstractcs read.
1036	  CHECK(reads_since_cmd > 0u);
1037	}
