TEST_CASE("resume throws when V-data sweep Program Buffer execution fails")
{
  // B1 regression: exec_progbuf used to return bool and four call sites
  // silently dropped the result. The very first PB exec inside resume() for a
  // V-state is the pb_v_data_sweep vsetvl (program_buffer.hpp:164); arming
  // fail_next_pb_exec makes that exec raise sticky cmderr, and the throw must
  // propagate through pb_v_data_sweep -> ResumeDriver::resume.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  bus.fail_next_pb_exec = true;

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_V;
  s.vlenb = 16;
  s.vl    = 8;
  s.vtype = 0xC1;

  hybrid::ResumeDriver driver(bus, kScratch);
  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
}

